p = 97
def add(P, Q):
    if P is None: return Q
    if Q is None: return P
    if P[0] == Q[0] and (P[1] + Q[1]) % p == 0: return None
    m = (3 * P[0] * P[0] * pow(2 * P[1], -1, p) if P == Q else (Q[1] - P[1]) * pow(Q[0] - P[0], -1, p)) % p
    x = (m * m - P[0] - Q[0]) % p
    return (x, (m * (P[0] - x) - P[1]) % p)
def mul(n, P):
    R = None
    while n:
        if n & 1: R = add(R, P)
        P = add(P, P); n >>= 1
    return R
